CREATE TABLE MONTHS (MID INT, MONTH INT);
CREATE TABLE WEEKDAYS (DID INT, DAY_OF_WEEK INT);
CREATE TABLE CARRIERS (CID INT, NAME INT);
CREATE TABLE FLIGHTS (FID INT, YEAR INT, MONTH_ID INT, DAY_OF_MONTH INT, CARRIER_ID INT);

counterexample:
INSERT INTO CARRIERS (CID, NAME) VALUES (1, 'CarrierA');
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (1, 2023, 1, 15, 1);
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (2, 2023, 1, 15, 1);
-- Repeat previous line to insert 1000 total flights for CarrierA on January 15, 2023.
-- Now, insert a flight for a different day of the month.
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (1002, 2023, 1, 16, 1);

schema:
CREATE TABLE MONTHS (MID INT, MONTH INT);
CREATE TABLE WEEKDAYS (DID INT, DAY_OF_WEEK INT);
CREATE TABLE CARRIERS (CID INT, NAME INT);
CREATE TABLE FLIGHTS (FID INT, YEAR INT, MONTH_ID INT, DAY_OF_MONTH INT, CARRIER_ID INT);

counterexample:
INSERT INTO CARRIERS (CID, NAME) VALUES (1, 'CarrierA');
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (1, 2020, 6, 15, 1);
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (2, 2021, 6, 15, 1);
/* Add 1000 more flights on the same day of different months or years */
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) SELECT generate_series(3, 1003), 2021, 7, 15, 1;
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) SELECT generate_series(1004, 2004), 2021, 8, 15, 1;
/* Now CarrierA will appear in Q2's result but not necessarily in Q1's result if the individual year-month-day combinations do not exceed 1000 */

